import java.util.Arrays;

public class Main {
    public static void main(String[] args) {
        String[] cities = {"Lima", "Oslo", "Cairo"};
        int[] temps = {22, 31, 25, 18, 29};

        for (String city : cities) {
            System.out.println("City: " + city);
        }

        int hot = 0;
        for (int t : temps) {
            if (t > 25) {
                hot++;
            }
