import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<Integer> ratings = new ArrayList<>(List.of(4, 1, 5, 3, 2, 1, 4));

        int sum = 0;
        for (int r : ratings) {
            sum += r;
        }
        System.out.printf("Average: %.2f%n", (double) sum / ratings.size());

        for (int i = 0; i < ratings.size(); i++) {
            int rating = ratings.get(i);
            if (rating > 3) {
                System.out.println("Position " + (i + 1) + ": " + rating);
            }
        }

        Iterator<Integer> it = ratings.iterator();
        while (it.hasNext()) {
            int r = it.next();
            if (r < 2) {
                it.remove();
            }
        }
        System.out.println("Kept: " + ratings);
    }
}
